mapper.select:
select A.nickname, A.email, A.birth, B.imgpath, B.universe, B.univsub , B.sexual, B.career, C.subcate, C.represent, C.title, C.subcate0, C.price1, C.price3, C.subcate1, C.opt1price3 , C.subcate2, C.opt2price3 ,C.id, C.readcount
from members as A, profile as B, lesson as C where A.email=B.email and B.email=C.email and A.membership=1 and C.visible=1


	 and C.cate=#{subject} order by readcount desc limit #{firstRow}, #{endRow}


	 and C.subcate like concat('%',#{subject},'%') order by readcount desc limit #{firstRow}, #{endRow}

select count(*) from lesson as A, profile as B, members as C where C.membership=1 and A.visible=1 and B.locales like concat('%',#{locale},'%') and B.career>=#{career}
 and B.sexual like concat('%',#{sexual},'%') and A.email = B.email and C.email = B.email


	   and A.cate=#{subject} 


	  and A.subcate like concat('%',#{subject},'%')

select A.nickname, A.email, A.birth, B.imgpath, B.universe, B.univsub , B.sexual, B.career, C.subcate, C.represent, C.title, C.subcate0, C.price1, C.price3, C.subcate1, C.opt1price3 , C.subcate2, C.opt2price3 , C.id, C.readcount
from members as A, profile as B, lesson as C where A.email=B.email and B.email=C.email and A.membership=1 and C.visible=1 and B.locales like concat('%',#{locale},'%') and B.career>=#{career} 
 and B.sexual like concat('%',#{sexual},'%')


	 	and C.cate=#{subject}  order by id desc limit #{firstRow}, #{endRow}



	 	and C.cate=#{subject}  order by readcount desc limit #{firstRow}, #{endRow}



	 	and C.subcate like concat('%',#{subject},'%')  order by id desc limit #{firstRow}, #{endRow}



	 	and C.subcate like concat('%',#{subject},'%')  order by readcount desc limit #{firstRow}, #{endRow}

		select A.email, A.name ,A.nickname, A.phone ,B.sexual, C.represent, C.title, C.cate, C.subcate, C.gawe, C.trial, C.visible ,


   		     C.subCate0, C.price1, C.price2, C.price3 from members as A, profile as B, lesson as C where A.email=#{email} and B.email=#{email} and C.id=#{id}


   		     C.subCate1, C.opt1price1, C.opt1price2, C.opt1price3 from members as A, profile as B, lesson as C where A.email=#{email} and B.email=#{email} and C.id=#{id}


   		     C.subCate2, C.opt2price1, C.opt2price2, C.opt2price3 from members as A, profile as B, lesson as C where A.email=#{email} and B.email=#{email} and C.id=#{id}
